def render(params, viewmat):
    img, _, _ = rasterization(
        params["means"], params["quats"], torch.exp(params["scales"]), torch.sigmoid(params["opacities"]),
        params["sh0"], viewmat[None], K[None], W, H, sh_degree=0, packed=False)
    return img[0].clamp(0, 1)

def psnr(a, b):
    # Peak signal-to-noise ratio in dB: higher = closer to the photo. ~20 is rough, 30+ is very good.
    return (-10 * torch.log10(((a - b) ** 2).mean())).item()

def mean_test_psnr(params):
    with torch.no_grad():
        return float(np.mean([psnr(render(params, v), gt) for v, gt in test_views]))

